pragma solidity >=0.8.0;
contract StoragePackingProbe {
    uint8 public a;
    bool public b;
    int32 public c;
    uint8 public d;
    uint256 public wide;
    string public text;
    uint8[4] public arr;

    function setSmall(uint8 _a, bool _b, int32 _c, uint8 _d) public {
        a = _a; b = _b; c = _c; d = _d;
    }
    function setWide(uint256 w) public { wide = w; }
    function setText(string memory t) public { text = t; }
    function setArr(uint256 i, uint8 v) public { arr[i] = v; }
    function clearA() public { delete a; }
    function length() public view returns (uint256) { return bytes(text).length; }
}
